// Check if today is a weekday (safety check beyond cron)
const now = new Date();
const day = now.getDay(); // 0=Sun, 6=Sat

if (day === 0 || day === 6) {
  console.log('Weekend - skipping cadence run');
  return [];
}

return [{ json: { run_date: now.toISOString(), day_of_week: day } }];

// Calculate which leads need an email today
const leads = $input.all().map(i => i.json);
const today = new Date();
today.setHours(0, 0, 0, 0);

const readyToSend = [];

for (const lead of leads) {
  if (!lead.cadence_started_at) continue;

  const startDate = new Date(lead.cadence_started_at);
  startDate.setHours(0, 0, 0, 0);
  const daysSinceStart = Math.floor((today - startDate) / (1000 * 60 * 60 * 24));

  // Get cadence steps (from cadences table via join or stored in lead)
  // Step delays: [0, 3, 7, 12]
  const stepDelays = [0, 3, 7, 12];
  const currentStep = lead.cadence_step || 0;

  if (currentStep >= stepDelays.length) {
    continue; // All steps completed
  }

  const targetDay = stepDelays[currentStep];

  if (daysSinceStart >= targetDay) {
    readyToSend.push({
      ...lead,
      _current_step: currentStep,
      _days_since_start: daysSinceStart,
      _target_day: targetDay
    });
  }
}

console.log(`Cadence Engine: ${leads.length} active leads, ${readyToSend.length} ready to send`);

return readyToSend.map(lead => ({ json: lead }));

// For each lead:
// 1. Find the correct template for their cadence step
// 2. Replace variables
// 3. Select a domain (round-robin)
// 4. Build the email payload

const leads = $('Calculate Send Schedule').all().map(i => i.json);
const domains = $('Fetch Active Domains').all().map(i => i.json)
  .filter(d => d.sent_today < d.daily_limit);
const templates = $('Fetch Templates').all().map(i => i.json);

if (domains.length === 0) {
  console.log('No domains available (all at daily limit)');
  return [];
}

const emailsToSend = [];
let domainIndex = 0;

for (const lead of leads) {
  // Find template for current step
  const template = templates.find(t => 
    t.cadence_id === lead.cadence_id && 
    t.step_number === lead._current_step &&
    t.version === (lead.custom_fields?.variant || 'A')
  );

  if (!template) {
    console.log(`No template found for lead ${lead.id} step ${lead._current_step}`);
    continue;
  }

  // Select domain (round-robin)
  const domain = domains[domainIndex % domains.length];
  domainIndex++;

  // Check domain limit
  if (domain.sent_today >= domain.daily_limit) continue;

  // Replace template variables
  let subject = template.subject || '';
  let body = template.body || '';

  const vars = {
    first_name: lead.first_name || '',
    last_name: lead.last_name || '',
    company_name: lead.company_name || '',
    role: lead.role || '',
    industry: lead.industry || ''
  };

  for (const [key, value] of Object.entries(vars)) {
    subject = subject.replace(new RegExp(`\\{\\{${key}\\}\\}`, 'g'), value);
    body = body.replace(new RegExp(`\\{\\{${key}\\}\\}`, 'g'), value);
  }

  // Build thread headers for follow-up emails (step > 0)
  const threadHeaders = {};
  if (lead._current_step > 0 && lead.custom_fields?.first_message_id) {
    threadHeaders['In-Reply-To'] = lead.custom_fields.first_message_id;
    threadHeaders['References'] = lead.custom_fields.first_message_id;
  }

  emailsToSend.push({
    lead_id: lead.id,
    lead_email: lead.email,
    lead_name: `${lead.first_name} ${lead.last_name || ''}`.trim(),
    from_email: `leveron@${domain.domain}`,
    from_name: 'Leveron',
    reply_to: `respostas@${domain.domain}`,
    subject: subject,
    body_text: body,
    body_html: body.replace(/\n/g, '<br>'),
    domain_id: domain.id,
    domain_name: domain.domain,
    template_id: template.id,
    cadence_step: lead._current_step,
    thread_headers: threadHeaders,
    list_unsubscribe: `<mailto:unsubscribe@${domain.domain}?subject=unsubscribe>`,
    _domain_sent_today: domain.sent_today
  });

  // Increment local counter
  domain.sent_today++;
}

console.log(`Prepared ${emailsToSend.length} emails to send`);
return emailsToSend.map(e => ({ json: e }));

// Post-send: update lead and create interaction
const email = $('Prepare Emails').first().json;
const sendResult = $('Send via Resend API').first().json;

const messageId = sendResult.id || `msg_${Date.now()}`;
const success = !sendResult.error;

return [{
  json: {
    // Lead update
    lead_id: email.lead_id,
    update: {
      emails_sent: '{{ leads.emails_sent + 1 }}',
      last_contacted_at: new Date().toISOString(),
      cadence_step: email.cadence_step + 1,
      custom_fields: {
        last_message_id: messageId,
        first_message_id: email.cadence_step === 0 ? messageId : undefined
      }
    },
    // Interaction record
    interaction: {
      lead_id: email.lead_id,
      type: 'email_sent',
      channel: 'email',
      metadata: {
        template_id: email.template_id,
        domain: email.domain_name,
        subject: email.subject,
        message_id: messageId,
        step_number: email.cadence_step,
        resend_id: sendResult.id,
        success: success
      }
    },
    // Domain update
    domain_id: email.domain_id,
    success: success
  }
}];
